begin;
set local role postgres;
set local search_path = public, extensions;create extension if not exists pgtap with schema extensions;select plan(4);select is((select count(*) from pg_policies where schemaname='public' and tablename='audit_logs' and cmd='INSERT'),0::bigint,'No client insert policy remains');select table_privs_are('public','audit_logs','authenticated',array['SELECT'],'Authenticated users cannot forge audit rows');select function_privs_are('public','write_audit_log',array['uuid','text','text','uuid','jsonb'],'authenticated',array[]::text[],'Clients cannot call audit writer');select function_privs_are('public','write_audit_log',array['uuid','text','text','uuid','jsonb'],'service_role',array['EXECUTE'],'Service boundary can write audit rows');select * from finish();rollback;
